    # rails at the outer edges (4 on the left, 7 on the right) are markers.
    bars = []
    c = 0
    while c < w:
        color = g[axis][c]
        if color in (6, 8, 9) or (c == 0 and color == 4) or (c == w - 1 and color == 7):
            c += 1
            continue

        start = c
        while c < w and g[axis][c] == color:
            c += 1
        end = c

        up = 0
        while axis - up - 1 >= 0 and g[axis - up - 1][start] == color:
            up += 1
        down = 0
        while axis + down + 1 < h and g[axis + down + 1][start] == color:
            down += 1

        bars.append((start, end, color, up + down + 1))

    # When the bars have distinct colors, reorder their heights increasingly
    # from left to right. Make every resulting bar odd-height and centered.
    if bars and len({b[2] for b in bars}) == len(bars):
        heights = sorted(n if n % 2 else n + 1 for _, _, _, n in bars)
        for (start, end, color, old_height), new_height in zip(bars, heights):
            for col in range(start, end):
                r = axis - 1
                while r >= 0 and g[r][col] == color:
                    g[r][col] = 8
                    r -= 1
                r = axis + 1
                while r < h and g[r][col] == color:
                    g[r][col] = 8
                    r += 1

            top = max(0, axis - new_height // 2)
            bottom = min(h - 1, axis + new_height // 2)
            for col in range(start, end):
                for r in range(top, bottom + 1):
                    g[r][col] = color

    # A 7 marker at the far right extends to the tallest bar.
    if bars and g[axis][w - 1] == 7:
        height = max(n if n % 2 else n + 1 for _, _, _, n in bars)
        r = axis - 1
        while r >= 0 and g[r][w - 1] == 7:
            g[r][w - 1] = 8
            r -= 1
        r = axis + 1
        while r < h and g[r][w - 1] == 7:
            g[r][w - 1] = 8
            r += 1
        for r in range(max(0, axis - height // 2), min(h, axis + height // 2 + 1)):
            g[r][w - 1] = 7

    return g
